INSERT INTO libro_recuerdos (id, nombre, mensaje, icono, color, likes, media_ref, ip, created_at) VALUES ('1', 'Familia Avendaño Rivera', 'Hija amada, verte cumplir tus 15 años es el regalo más hermoso de nuestras vidas. Que Dios ilumine tu camino siempre. ¡Te amamos infinitamente! 💖👑', '👑', 'gold', '34', NULL, '127.0.0.1', '2026-10-04 20:45:00');
INSERT INTO libro_recuerdos (id, nombre, mensaje, icono, color, likes, media_ref, ip, created_at) VALUES ('2', 'Tía Carmen & Primos', '¡Felicidades Angie preciosa! Una noche inolvidable, te veías radiante como un cuento de hadas. ¡Que todos tus sueños se hagan realidad! ✨🥂', '✨', 'emerald', '22', NULL, '127.0.0.1', '2026-10-04 21:10:00');
INSERT INTO libro_recuerdos (id, nombre, mensaje, icono, color, likes, media_ref, ip, created_at) VALUES ('3', 'Tus Mejores Amigas del Cole', '¡La mejor fiesta de 15 del mundo! Bailamos sin parar toda la noche. ¡Te amamos muchísimo mejor amiga! 💃💕🎂', '💖', 'rose', '29', NULL, '127.0.0.1', '2026-10-04 21:30:00');
INSERT INTO libro_recuerdos (id, nombre, mensaje, icono, color, likes, media_ref, ip, created_at) VALUES ('4', 'Padrinos de Angie', 'Orgullosos de verte convertida en una señorita tan dulce, inteligente y llena de luz. Siempre estaremos para apoyarte. ¡Feliz cumpleaños! 🌟🥂', '🥂', 'cream', '18', NULL, '127.0.0.1', '2026-10-04 21:50:00');
INSERT INTO libro_recuerdos (id, nombre, mensaje, icono, color, likes, media_ref, ip, created_at) VALUES ('5', 'Tia Elena', 'Felicidades Angie hermosa!', '💖', 'rose', '0', NULL, '127.0.0.1', '2026-10-18 23:03:37');
